          {steps.map((step) => (
            <div key={step.number} className="flex flex-col items-center text-center">
              <div className="flex items-center justify-center w-16 h-16 rounded-full bg-indigo-600 text-white text-2xl font-bold mb-4 shadow-md">
                {step.number}
              </div>
              <h3 className="text-xl font-semibold text-gray-800">{step.title}</h3>
            </div>
          ))}
        </div>
      </div>
